// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        uint initialBalance = 1 ether;
        address owner = address(this);
        vm.deal(address(c), initialBalance);
        vm.deal(owner, 10 ether);

        vm.prank(owner);
        c.sendMoney(address(1), 1 wei, "");

        assertTrue(address(c).balance == initialBalance - 1 wei);
    }
}
